import{z as p,x as d,o,c as C,q as i,j as l,D as n,d as t,s,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"信道容量","description":"","frontmatter":{"title":"信道容量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/channel-capacity.md","filePath":"cs/channel-capacity.md","lastUpdated":1791413859000}'),m={name:"cs/channel-capacity.md"};function A(h,a,B,c,f,u){const r=d("Mermaid");return o(),C("div",null,[a[2]||(a[2]=i('<h1 id="信道容量" tabindex="-1">信道容量 <a class="header-anchor" href="#信道容量" aria-label="Permalink to &quot;信道容量&quot;">​</a></h1><div class="epigraph"><p>噪声信道的互信息最大值 $C=\\max_{p(x)}I(X;Y)$ 是可靠通信速率的上确界；低于 $C$ 可做到错误指数趋于零。</p><footer>—— 据 Shannon, 1948；Cover and Thomas 整理</footer></div><p><a href="/cs/lz77-lz78">上一课</a>把 LZ 接到信源编码的工程极限。信源一侧从定理到 Huffman、算术、LZ 已逼近 \\(H\\)。缺口是<strong>有噪信道</strong>：<a href="/cs/mutual-information">互信息</a> 在主干已定义，\\(C=\\max I(X;Y)\\) 尚未当容量用。本课钉信道编码定理的陈述，不构造具体码（下一课汉明）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信道 \\(p(y|x)\\)。发送 \\(X\\)，接收 \\(Y\\)。无噪声时 \\(Y=X\\)，\\(C=\\log|\\mathcal{X}|\\)。二元对称信道（BSC）翻转概率 \\(f\\)，\\(C=1-h(f)\\)，\\(h\\) 二元熵。<span class="marginnote">数字实例：取 \\(f=0.11\\)，则 \\(h(0.11)\\approx 0.11\\times 3.18 + 0.89\\times 0.17 \\approx 0.5\\)，于是 \\(C\\approx 1-0.5 = 0.5\\) 比特/次使用。意思是：每 11% 的随机翻转，就把这条二元管道的可靠吞吐量砍掉一半。</span>定理：速率 \\(R\\lt C\\) 存在码，块长 \\(\\to\\infty\\) 时解码错误 \\(\\to 0\\)；\\(R\\gt C\\) 则不能。<span class="marginnote">常见误区：初学者容易以为超过容量只是「错误率高一点、凑合能用」。实际是错误概率存在一个压不下去的正下界，什么码都救不回来；带重传的系统本质上是靠降低有效速率（同一份数据发多遍）退回 \\(R\\lt C\\)。</span>随机编码：从 \\(p(x)^n\\) 抽码本，典型译码。</p><p>与信源定理对偶：那里压到 \\(H\\)，这里扩到至少每符号 \\(H(X)/C\\) 的信道符号（分离原理：先压再抗噪，点名）。</p><h3 id="容量不是「信噪比公式」" tabindex="-1">容量不是「信噪比公式」 <a class="header-anchor" href="#容量不是「信噪比公式」" aria-label="Permalink to &quot;容量不是「信噪比公式」&quot;">​</a></h3><p>连续高斯信道 \\(C=\\frac12\\log(1+\\mathrm{SNR})\\) 是同一 \\(I(X;Y)\\) 的最大化，本课以离散为主，高斯点名。工程里的「达到容量」是 LDPC/Turbo 的后课，不是本课公式已经给了构造。</p><p><span class="marginnote">Shannon 1948 第 IV–V 部分。Cover–Thomas 第 7 章。Feinstein、Gallager 的误差指数本课不写。主干<a href="/cs/entropy-bits">熵</a> 已把 \\(C\\) 点名为后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 BSC 的 \\(C\\)。画：信息比特 \\(\\to\\) 加冗余 \\(\\to\\) 噪声 \\(\\to\\) 译码。强调存在性（随机码）vs 构造性。不要把汉明码的 \\(4/7\\) 速率写成容量——那是具体 \\(d_{\\min}\\) 码，远低于一般 \\(f\\) 下的 \\(C\\)。</p>',11)),(o(),l(E,null,{default:n(()=>[s(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PX%5B%22%E9%80%89%20p(x)%22%5D%20--%3E%20IXY%5B%22I(X%3BY)%22%5D%0A%20%20IXY%20--%3E%20C%5B%22C%20%3D%20max%20I%22%5D%0A%20%20C%20--%3E%20THM%5B%22R%EF%BC%9CC%20%E5%8F%AF%E9%9D%A0%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[t("有了 \\(C\\)，冗余的目标从「检几位错」升到「速率对容量的缝隙」。"),e("a",{href:"/cs/hamming-distance"},"汉明距离"),t(" 仍管最坏翻转；\\(C\\) 管典型噪声。两把尺子后课码会同时用。")],-1)),a[5]||(a[5]=e("p",null,"分离：最优不必是一次完成的联合信源信道码，i.i.d. 下分开几乎不损失。",-1)),a[6]||(a[6]=e("p",null,"「先压再抗噪」两级流水线，是分离原理的全貌：",-1)),(o(),l(E,null,{default:n(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E5%8E%9F%E5%A7%8B%E4%BF%A1%E6%BA%90%22%5D%20--%3E%20COMP%5B%22%E4%BF%A1%E6%BA%90%E7%BC%96%E7%A0%81%3A%20%E5%8E%8B%E5%88%B0%20H%20%E6%AF%94%E7%89%B9%2F%E7%AC%A6%E5%8F%B7%22%5D%0A%20%20COMP%20--%3E%20CH%5B%22%E4%BF%A1%E9%81%93%E7%BC%96%E7%A0%81%3A%20%E5%8A%A0%E5%86%97%E4%BD%99%2C%20%E9%80%9F%E7%8E%87%20R%20%3C%20C%22%5D%0A%20%20CH%20--%3E%20NOISE%5B%22%E7%A9%BF%E8%BF%87%E5%99%AA%E5%A3%B0%E4%BF%A1%E9%81%93%22%5D%0A%20%20NOISE%20--%3E%20DEC%5B%22%E4%BF%A1%E9%81%93%E8%AF%91%E7%A0%81%3A%20%E8%BF%98%E5%8E%9F%E5%8E%8B%E7%BC%A9%E6%B5%81%22%5D%0A%20%20DEC%20--%3E%20DECOMP%5B%22%E4%BF%A1%E6%BA%90%E8%AF%91%E7%A0%81%3A%20%E8%BF%98%E5%8E%9F%E5%8E%9F%E5%A7%8B%E4%BF%A1%E6%BA%90%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<p>随机编码：码本 i.i.d. 按达到容量的 \\(p(x)\\) 抽样，译码找与接收序列联合典型的码字。错误的并界在 \\(n\\to\\infty\\) 时 \\(\\to 0\\)。分离原理：先信源压到 \\(H\\)，再以 \\(R\\lt C\\) 信道编码，总资源 \\(H/C\\)。<span class="marginnote">术语翻译：总资源 \\(H/C\\) 的意思是——若信源每符号产出 \\(H=2\\) 比特、信道容量 \\(C=0.5\\) 比特/次，那每个信源符号平均要占 \\(2/0.5 = 4\\) 次信道使用。两道工序分开做，总账几乎不吃亏（i.i.d. 渐近意义下）。</span>联合编码在非 i.i.d. 或有限 \\(n\\) 上可能更好，本课不进。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证随机编码误差界全文，不引入网络信息论。不把 5G 调制当容量证明。后课默认：可靠速率以 \\(C\\) 为界。下一课具体二元码：汉明码。</p><p>容量是互信息的最大化，不是某一种码的 \\(d_{\\min}\\)。<span class="marginnote">直觉类比：容量像水管的口径——它只描述「这条管道最多能稳定通过多少水」，至于你用多粗的管嘴（汉明码、LDPC）去接到上限，是另一个工程问题，通常先留一道缝。</span>随机编码给存在性；下一课 Hamming 给构造，速率与 \\(C\\) 一般有缝。分离原理允许先压后抗噪。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(C=\\max I(X;Y)\\)；BSC 上 \\(1-h(f)\\)。</li><li>\\(R\\lt C\\) 可渐近无错；\\(R\\gt C\\) 不能。</li><li>存在性先于构造；距离码是下一课。</li><li>出处：Shannon, 1948；Cover and Thomas。</li></ul>',6))])}const _=p(m,[["render",A]]);export{F as __pageData,_ as default};
